import sys
from itertools import combinations

def solve():
    N, K = map(int, input().split())
    a = list(map(int, input().split()))

    unnecessary = 0
    total_sum = sum(a)

    for i in range(N):
        remaining_sum = total_sum - a[i]
        if remaining_sum < K:
            unnecessary += 1
        else:
            for j in range(1, N):
                for combo in combinations(range(N), j):
                    if i not in combo and sum(a[k] for k in combo) >= K:
                        break
                else:
                    unnecessary += 1
                    break

    print(unnecessary)

