import sys

def solve():
    N, K = map(int, input().split())
    A = list(map(int, input().split()))

    dp = [False] * (K + 1)
    dp[0] = True

    for a in A:
        for i in range(K, a - 1, -1):
            if dp[i - a]:
                dp[i] = True

    unnecessary = 0
    for i in range(N):
        if dp[K]:
            unnecessary += 1
        dp[K] = False
        for j in range(N):
            if i != j:
                for k in range(K, A[i] - 1, -1):
                    if dp[k - A[i]]:
                        dp[k] = True
        if dp[K]:
            unnecessary -= 1

    print(unnecessary)

solve()
